import dns from 'node:dns';
import { syncBuiltinESMExports } from 'node:module';
const resolver = new dns.promises.Resolver({ timeout: 5000, tries: 2 });
resolver.setServers(['1.1.1.1', '8.8.8.8']);
const nativeLookup = dns.lookup;
dns.lookup = function lookup(hostname, options, callback) {
  if (typeof options === 'function') { callback = options; options = {}; }
  if (typeof options === 'number') options = { family: options };
  options ??= {};
  if (!['austincarbuyingservice.com','www.austincarbuyingservice.com','driverightcarbuying.com','www.driverightcarbuying.com'].includes(hostname)) return nativeLookup(hostname, options, callback);
  const family = options.family || 4;
  const resolve = family === 6 ? resolver.resolve6(hostname) : resolver.resolve4(hostname);
  resolve.then(addresses => {
    if (options.all) callback(null, addresses.map(address => ({address, family})));
    else callback(null, addresses[0], family);
  }, error => callback(error));
};
syncBuiltinESMExports();
